package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.domain.BusinessProjectMember;import com.ruoyi.business.service.IBusinessProjectService;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class SaveProjectMemberCapability implements AiConfirmableCapability{private final IBusinessProjectService service;@Autowired public SaveProjectMemberCapability(IBusinessProjectService s){service=s;}public String code(){return "project.member.save";}public String description(){return "把人员加入项目或调整其项目身份。先查询项目和人员目录取得稳定ID；确认后执行。主负责人请使用负责人变更工具。";}public String requiredPermission(){return "business:project:member";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");AiSchemas.property(s,"staffUserId","number","人员ID");Map<String,Object>r=AiSchemas.property(s,"memberRole","string","DEPUTY/MEMBER/OBSERVER");r.put("enum",Arrays.asList("DEPUTY","MEMBER","OBSERVER"));AiSchemas.property(s,"staffName","string","用于确认展示的人员姓名");AiSchemas.property(s,"joinedDate","string","加入日期 YYYY-MM-DD");return AiSchemas.required(s,"projectId","staffUserId","memberRole");}public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){return "将“"+(text(in.get("staffName")).isEmpty()?"人员ID "+number(in.get("staffUserId")):text(in.get("staffName")))+"”加入项目或调整身份为 "+upper(in.get("memberRole"));}public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){BusinessProjectMember m=new BusinessProjectMember();m.setProjectId(number(in.get("projectId")));m.setUserId(number(in.get("staffUserId")));m.setMemberRole(upper(in.get("memberRole")));m.setJoinedDate(date(in.get("joinedDate")));BusinessProjectMember x=service.saveMember(m,i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",x.getProjectId());r.put("staffUserId",x.getUserId());r.put("staffName",x.getUserNameSnapshot());r.put("memberRole",x.getMemberRole());return r;}}
